let tutorialIndex=0,tutorialOpen=false,tutorialTarget=null;

function tutorialStorageKey(){return `nexo-tutorial-v1:${currentUser?.id||"local"}`}
function clearTutorialTarget(){tutorialTarget?.classList.remove("tutorial-target");tutorialTarget=null}
function closeTutorial(completed=true){clearTutorialTarget();tutorialOpen=false;document.querySelector("#tutorial-layer").hidden=true;document.querySelector("#sidebar").classList.remove("open");if(completed)localStorage.setItem(tutorialStorageKey(),"done")}
function showTutorialStep(){
  const step=tutorialSteps[tutorialIndex],sidebar=document.querySelector("#sidebar");clearTutorialTarget();
  if(step.route){location.hash=step.route;route()}
  sidebar.classList.toggle("open",Boolean(step.menu&&innerWidth<=900));
  document.querySelector("#tutorial-step").textContent=`PASO ${tutorialIndex+1} DE ${tutorialSteps.length}`;
  document.querySelector("#tutorial-icon").textContent=step.icon;document.querySelector("#tutorial-title").textContent=step.title;document.querySelector("#tutorial-copy").textContent=step.copy;
  document.querySelector("#tutorial-prev").disabled=tutorialIndex===0;document.querySelector("#tutorial-next").textContent=tutorialIndex===tutorialSteps.length-1?"Terminar":"Siguiente";
  document.querySelector("#tutorial-progress").innerHTML=tutorialSteps.map((_,i)=>`<i class="${i<=tutorialIndex?"active":""}"></i>`).join("");
  setTimeout(()=>{tutorialTarget=document.querySelector(step.target);if(tutorialTarget){tutorialTarget.classList.add("tutorial-target");if(!step.menu)tutorialTarget.scrollIntoView({behavior:"smooth",block:"center"})}},120);
}
function startTutorial(force=false){if(tutorialOpen||(!force&&localStorage.getItem(tutorialStorageKey())))return;tutorialOpen=true;tutorialIndex=0;document.querySelector("#tutorial-layer").hidden=false;showTutorialStep()}
function maybeStartTutorial(){const gate=document.querySelector("#access-gate");if(!gate.hidden)return;setTimeout(()=>startTutorial(false),450)}

function loadLocal(){try{return{...structuredClone(initial),...JSON.parse(localStorage.getItem("nucleo-state-demo")||localStorage.getItem("nucleo-state"))}}catch{return structuredClone(initial)}}
function localStateKey(){return currentUser?`nucleo-state:${currentUser.id}`:"nucleo-state-demo"}
function save(){
  localStorage.setItem(localStateKey(),JSON.stringify(state));
  if(currentUser&&isSocialConfigured()){
    clearTimeout(cloudTimer);
    cloudTimer=setTimeout(()=>saveLearningState(state).catch(()=>toast("Guardado local; la nube no respondió")),450);
  }
  updateChrome();
}
function uid(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`}
function escapeHTML(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function fmtDate(value,options={}){return new Intl.DateTimeFormat("es-GT",{day:"numeric",month:"short",...options}).format(new Date(value))}
function relative(value){const days=Math.ceil((new Date(value)-new Date())/864e5);if(days<0)return`Hace ${Math.abs(days)} día${Math.abs(days)===1?"":"s"}`;return days===0?"Hoy":days===1?"Mañana":`En ${days} días`}
function displayName(){return currentUser?.user_metadata?.full_name||currentUser?.user_metadata?.name||"Estudiante"}
function initials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"NU"}
function subjectMastery(key){const values=Object.values(state.mastery?.[key]||{}).filter(Number.isFinite);return values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):null}
function overallMastery(){const values=Object.keys(curriculum).map(subjectMastery).filter(Number.isFinite);return values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):null}
function masteryLabel(value){return Number.isFinite(value)?`${value}%`:"Sin diagnóstico"}
function levelInfo(){const level=Math.floor(Math.sqrt((state.xp||0)/100))+1,floor=(level-1)**2*100,ceiling=level**2*100,names=["Aprendiz","Explorador","Analista","Investigador","Maestro","Erudito"];return{level,name:names[Math.min(level-1,names.length-1)],progress:Math.round(((state.xp-floor)/(ceiling-floor))*100),next:ceiling-state.xp}}
function registerStudyDay(){const today=new Date().toISOString().slice(0,10);if(state.lastStudyDate===today)return;const yesterday=new Date(Date.now()-864e5).toISOString().slice(0,10);state.streak=state.lastStudyDate===yesterday?(state.streak||0)+1:1;state.lastStudyDate=today}
function awardXP(amount,reason){const before=levelInfo().level;state.xp+=amount;state.coins+=Math.ceil(amount/5);registerStudyDay();save();const after=levelInfo().level;toast(after>before?`¡Nivel ${after} desbloqueado!`:`+${amount} XP · ${reason}`)}
function supportedEvent(event){return Boolean(subjects[event.course])}
function sortedEvents(){return[...(state.events||[])].sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt))}
function shuffle(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}

