function route(){
  const key=location.hash.slice(1)||"inicio";
  const labels={inicio:["ESPACIO PERSONAL","Inicio"],agenda:["PLANIFICACIÓN","Mi agenda"],plan:["ADAPTATIVO","Plan personal"],diagnostico:["EVALUACIÓN","Diagnóstico"],misiones:["AVENTURA","Misiones"],grupo:["COLABORACIÓN","Grupo de estudio"],arena:["DESAFÍOS","Arena científica"],metodo:["SISTEMA","Mi método"],quimica:["ASIGNATURA","Química"],fisica:["ASIGNATURA","Física"],biologia:["ASIGNATURA","Biología"],calculo:["ASIGNATURA","Cálculo"]};
  document.querySelectorAll(".nav-item[data-route]").forEach(x=>x.classList.toggle("active",x.dataset.route===key));
  document.querySelector("#section-kicker").textContent=(labels[key]||labels.inicio)[0];document.querySelector("#section-title").textContent=(labels[key]||labels.inicio)[1];
  (pages[key]||renderHome)();document.querySelector("#sidebar").classList.remove("open");window.scrollTo({top:0,behavior:"smooth"});
}
function eventCard(event,compact=false){
  const s=subjects[event.course],icon=s?.icon||"□",cls=s?.cls||"other",course=s?.name||event.courseName||"Otro curso",topic=s&&event.topic?curriculum[event.course].topics[event.topic]?.name:"";
  const action=s?`<button class="go" data-study="${event.course}">Estudiar →</button>`:`<button class="go" data-complete="${event.id}">Completar</button>`;
  return`<div class="task event-${event.type} ${compact?"compact":""}"><span class="task-icon ${cls}">${event.type==="exam"?"!":icon}</span><div><strong>${escapeHTML(event.title)}</strong><small>${escapeHTML(course)}${topic?` · ${escapeHTML(topic)}`:""} · ${relative(event.dueAt)}, ${fmtDate(event.dueAt,{hour:"numeric",minute:"2-digit"})}</small></div>${action}</div>`;
}
