function nextPlanPreview(){const exam=sortedEvents().find(e=>e.type==="exam"&&supportedEvent(e)&&!state.completed.includes(e.id));if(!exam)return'<div class="empty">Añade un examen de Química, Física, Biología o Cálculo para generar un plan.</div>';const plan=state.plans[exam.id]||generateExamPlan(exam),next=plan.sessions.find(x=>new Date(`${x.date}T23:59`)>=new Date())||plan.sessions.at(-1);return`<div class="plan-preview"><span class="exam-chip">EXAMEN · ${relative(exam.dueAt)}</span><h3>${escapeHTML(exam.title)}</h3><p><strong>Siguiente:</strong> ${escapeHTML(next?.title||"Simulacro final")} · ${next?.minutes||30} min</p></div>`}
